#!/usr/bin/env python3
# Static checks for the shared profile installation coordinator (source level only; the real iOS service is not exercised here).
import re,sys
def R(p):return open(p,encoding='utf-8').read()
bad=[]
def need(c,m):
    if not c:bad.append(m)
core=R('Shared/MYBProfileInstall.h');helper=R('Helper/MYXXdev.m');stage=R('Helper/MYBProfileStage.inc');web=R('Preferences/MYBWebController.m')
dns=R('Preferences/MYBDNSController.m');leg=R('Preferences/MYBLegacyController.m');args=R('Shared/MYBHelperArgs.h');menu=R('Preferences/MYBMenuBase.m')
need('queueFileDataForProfileInstallation:originalFileName:outError:' in core and 'queueProfileDataForInstallation:outError:' in core,'both staging selectors are named')
need('MYBProfileEncodingOK' in core,'a method is called only when its type encoding matches')
need('"profilestage"' in helper.replace('@"','"') or 'profilestage' in helper,'helper dispatches profilestage')
need('profilestage' in args and 'profilestatus' in args,'the helper argument table lists both profile actions')
need('MYBBootstrapRoot()' in stage and '@[@"dns",@"profiles"]' in stage,'the helper only reads the two bundled profile folders')
need('invertedSet' in stage,'profile names are restricted to plain characters')
need('MYBOpenInstaller' in web and 'MYBProfileBusy' in web,'the installer opens through one coordinator that ignores repeated taps')
need(web.index('profilestage')<web.index('MYBOpenInstaller(MYBProfileInstallerURLs()'),'Settings is opened only after staging was requested')
need('rc==0' in web and 'MYBOpenInstaller(MYBProfileInstallerURLs()' in web and 'Save Profile to Files' in web and 'Copy Profile Link' in web and 'Open Device Management' in web,'staging success opens the installer; failures offer the three fallbacks')
need('Installed' in core and 'Not Installed' in core and 'Unable to Check' in core,'the three status labels exist')
need('MYBDeliverProfileFile' in dns and 'MYBDeliverProfileFile' in leg,'DNS and Legacy share one delivery path')
need('MYBRefreshProfileStatus' in dns and 'MYBRefreshProfileStatus' in leg,'both screens read installed state back')
need('"identifier"' in leg.replace('@"','"') and 'pendingPath' in leg,'the Legacy pending choice carries the profile identifier')
need('replace' in args and 'MYBAskReplaceWaitingProfile' in web and 'rc==6||rc==7' in web,'a waiting or unknowable profile queue is put to the person before anything is replaced')
need('popProfileDataFromHeadOfInstallationQueue' not in re.sub(r'//[^\n]*','',core+stage),'the destructive queue pop is never called outside comments')
need('profilestage' in menu and 'profilestatus' in menu,'profile helper steps are quiet so the coordinator shows its own messages')
need('installed' not in re.sub(r'(?s)/\*.*?\*/|//[^\n]*','',stage.split('stageBundledProfile')[1].split('checkBundledProfile')[0]).lower().replace('notinstalled',''),'staging never records installed')
if bad:
    print('\n'.join('FAIL: '+b for b in bad));sys.exit(1)

# the six Legacy profiles share one identifier: status, staging record and pending choice are keyed by identifier AND PayloadUUID
_inc=open('Helper/MYBProfileStage.inc').read();_web=open('Preferences/MYBWebController.m').read()
need('MYBProfileInstalledStateFor' in _inc and 'checks[info[@"key"]]' in _inc and 'checks[identifier]' not in _inc,'the helper checks each profile by identifier and PayloadUUID, not by identifier alone')
need('stagedDigests' in _inc and 'MYBProfileDisplayLabel' in _web and 'record[@"checks"][identifier]' not in _web,'the profile row is looked up by key and can show Accepted, Not Confirmed')
need('MYBRefreshProfileStatus(self,@"profiles",files,nil)' in leg and 'files.firstObject' not in leg and '@"key"' in leg,'every Legacy profile is checked on its own, and the pending choice carries the key')
print('Profile installation source checks passed.')
inst=R('Shared/MYBProfileInstall.h');mig=R('Helper/MYBProfileMigrate.inc');hargs=R('Shared/MYBHelperArgs.h')
need('kMCSettingsURLProfilePurgatoryInstallation' in inst and 'openSensitiveURL:withOptions:' in inst,'the installer is opened with Apple\u2019s constant and openSensitiveURL:withOptions:, not only a hardcoded prefs URL')
need('MYBOpenProfileInstallerSensitive()' in stage and 'return [nav[@"opened"] boolValue]?0:8;' in stage and stage.index('queueFile')<stage.index('MYBOpenProfileInstallerSensitive()') if 'queueFile' in stage else 'MYBProfileStage(' in stage,'the helper opens the installer only after iOS accepted the staged profile')
need('rc==8' in web and 'MYBDeliveryFailed' in web,'staged-but-not-opened falls back to the app routes; an outright refusal restores a changed state')
need('legacytransaction' in leg and 'restoreNativeAfterLegacy' in leg and 'Restore Native Protection' in leg,'Legacy keeps a transaction record and always offers the way back to native protection')
need('profilediag' in hargs and 'MYBProfileDiagnostics' in mig and 'Copy Profile Diagnostics' not in R('Preferences/MYBTroubleshootingController.m'),'the profile diagnostics collector stays in the helper; the Troubleshooting row for it was retired')
need('queueFileDataForAcceptance:originalFileName:forBundleID:outError:' in core and 'queueFileDataForAcceptance:originalFileName:outError:' in core and 'peekProfileDataFromPurgatoryForDeviceType:withCompletion:' in core and 'queueProfileDataForInstallation:originalFileName:originatingBundleID:transitionToUI:completion:' in core,'the acceptance, asynchronous and peek interfaces are all implemented, each behind an exact-encoding check')
need('Direct Install Not Available' not in web and 'on This iOS Version' not in web,'staging failures are no longer blamed on the iOS version')
need('MYBProfileFailureMessage' in web and 'MYBStageInSettings' in web and '[settings] stage' in web,'a failed helper attempt is retried from the Settings component and both outcomes are recorded')
need('MYBProfileProbeLines(@"helper")' in mig,'the helper still collects the probe lines')
need('legacypreflight' not in leg and leg.count('@"legacyprepare"')==1 and leg.index('@"legacyprepare"')<leg.index('MYBDeliverProfileFile(self'),'native protection is turned off BEFORE the profile is delivered, because iOS refuses to install it while the managed link exists')
need('restoreNativeAfterCancelledSwitch' in leg and leg.count('@[@"enable"]')>=2 and 'Profile Not Installed Yet' not in leg,'a profile that is not installed (cancelled, failed, never started) turns native protection back on automatically')
need('MYBLegacyRevertCheck' in R('Helper/MYBAppControl.inc') and 'LegacyRevert.plist' in R('Helper/MYXXdev.m') and 'wasOn' in R('Helper/MYXXdev.m'),'the helper turns native protection back on after 15 minutes if a Legacy switch is abandoned')
need('_queueDataForAcceptance:originalFileName:originatingBundleID:transitionToUI:outError:' in core and 'peekProfileDataFromPurgatoryForDeviceType:"' in core,'the direct-to-UI route and the synchronous peek seen on the device are implemented')
need(web.index('MYBStageInSettings(folder,file,replace')<web.index('MYBStageViaHelper(owner,folder,file,label,link,replace,r)') and 'static void MYBStageProfile' in web,'the Settings component stages first; the helper is only the fallback')
alert=R('Companions/MYBProfileAlert/Tweak.xm')
need('v@:@@@@@@@BBBd@@?' in alert and 'method_getTypeEncoding' in alert and alert.index('v@:@@@@@@@BBBd@@?')<alert.index('%init(Quiet)'),'the alert hook is installed only when the method has exactly the shape read from the device')
need('profilealert.plist' in alert and 'profilealert.plist' in web and web.index('profilealert.plist')<web.index('MYBProfileStage(conn'),'the alert is shortened only while MYbloXX\u2019s own marker, written before the service call, is fresh')
need('%orig(' in alert and 'ScalarOnly(sig)' in alert and 'cCsSiIlLqQB' in alert and 'completion()' not in alert and '((void(^)' not in alert and alert.index('ScalarOnly(sig)')<alert.index('CallWithZeros(block,sig)'),'the alert is skipped, and its completion run, only when the block\u2019s own signature shows plain numbers; otherwise the original runs with a short dismiss')
need('com.apple.managedconfiguration' in R('Companions/MYBProfileAlert/MYBProfileAlert.plist') and 'Companions/MYBProfileAlert' in R('Makefile'),'the alert hook is filtered to the ManagedConfiguration bundle and built with the package')

